/* Local workbook export. No server or Notion connection. */
(function(root){'use strict';
const copy=x=>JSON.parse(JSON.stringify(x));
function dateStamp(d=new Date()){return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function safeName(s){s=String(s||'未命名实验').normalize('NFC').replace(/[<>:"/\\|?*\x00-\x1f]/g,'_').replace(/[. ]+$/g,'').slice(0,70);if(!s||/^\.+$/.test(s))s='未命名实验';if(/^(con|prn|aux|nul|com[1-9]|lpt[1-9])(?:\.|$)/i.test(s))s='_'+s;return s}
function unique(name,used){let n=safeName(name),v=n,i=2;while(used.has(v.toLowerCase()))v=n+' ('+(i++)+')';used.add(v.toLowerCase());return v}
function source(log){const s=log.workbench?.source||log.data;if(!s||typeof s.raw!=='string')return null;const ext=/\.(txt|csv|tsv|zip)$/i.exec(s.filename||'')?.[1]?.toLowerCase()||'txt';return {ext,raw:s.originalBase64?Uint8Array.from(atob(s.originalBase64),c=>c.charCodeAt(0)):s.raw,exact:!!s.originalBase64}}
function capture(design){return root.captureOpticalDiagram(design)}
const help='Notion 导入：在桌面版/网页版页面输入 /zip，选择 Convert Zip to pages，上传日期目录中的“全部实验-Notion.zip”（重名时带序号），全部 Sheet 合并为一篇 experiment 笔记。也可 设置 → 导入 → ZIP。不要仅拖入页面当附件。\n只导入文字：解压该 ZIP，设置 → 导入 → Text & Markdown，选择 experiment.md。图片请连同 ZIP 导入。Markdown 是文本标记格式，Notion 将其转换成页面块，不运行代码。复杂表格可能需要调整。\n原始数据放在日期目录，以实验名命名。新导入文件保留原始字节；旧工程仅保留已解码原文，会按 UTF-8 输出。没有原始数据的实验仅导出日志，不伪造原文件。重复名称或再次导出会加序号，避免覆盖。\n';
async function prepare(input,used=new Set(),render=capture){const book=root.SheetCore.sync(input).experimentBook,files={},manifest=[],packs=[];for(const sh of book.sheets){const design=copy(sh.scene),log=design.labLog||{},meta={title:sh.name,...log.meta},name=unique(meta.title,used),original=source(log),diagram={...design};delete design.labLog;delete design.experimentBook;const args={meta,data:log.data,workbench:log.workbench,polarizationAngles:log.polarizationAngles,design,...render(diagram)};let nf;try{nf=await root.NotionExport.files(args)}catch(e){throw Error(name+'：'+e.message)}files[name+'/'+name+'.html']=root.LabLogCore.report(args);packs.push(nf);for(const [path,value]of Object.entries(nf)){if(!path.endsWith('.md'))files[name+'/本地附件/'+path.replace('experiment/assets/','')]=value}files[name+'/'+name+'.json']=JSON.stringify(sh.scene,null,2);if(original)files[name+'.'+original.ext]=original.raw;manifest.push({experiment:meta.title,folder:name,originalFile:original?name+'.'+original.ext:null,originalBytesPreserved:original?.exact||false})}files[unique('全部实验-Notion',used)+'.zip']=root.NotionExport.zip(root.NotionExport.combine(packs,dateStamp()+' 实验记录'));files['导出说明-'+Date.now()+'.txt']=help+'\n'+JSON.stringify(manifest,null,2);return files}
async function writeFiles(dir,files){let done=0;try{for(const [path,content]of Object.entries(files)){const parts=path.split('/');let d=dir;for(const p of parts.slice(0,-1))d=await d.getDirectoryHandle(p,{create:true});const h=await d.getFileHandle(parts.at(-1),{create:true}),w=await h.createWritable();try{await w.write(content);await w.close()}catch(e){await w.abort().catch(()=>{});throw e}done++}}catch(e){throw Error('写入失败；已写入 '+done+' 个文件，目标目录可能有部分结果：'+e.message)}return done}
async function folder(input,chosen){const stamp=dateStamp(),dir=await chosen.getDirectoryHandle(stamp,{create:true}),used=new Set();for await(const [name] of dir.entries()){used.add(name.toLowerCase());used.add(name.replace(/\.(txt|csv|tsv|zip)$/i,'').toLowerCase())}const files=await prepare(input,used);await writeFiles(dir,files);return stamp}
async function download(input){const stamp=dateStamp(),files=await prepare(input),data=root.NotionExport.zip(Object.fromEntries(Object.entries(files).map(([k,v])=>[stamp+'/'+k,v]))),a=document.createElement('a'),u=URL.createObjectURL(new Blob([data],{type:'application/zip'}));a.href=u;a.download=stamp+'-实验日志.zip';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
async function downloadNotion(input){const book=root.SheetCore.sync(input).experimentBook,packs=[];for(const sh of book.sheets){const design=copy(sh.scene),log=design.labLog||{},diagram={...design};delete design.labLog;delete design.experimentBook;try{packs.push(await root.NotionExport.files({meta:{title:sh.name,...log.meta},data:log.data,workbench:log.workbench,polarizationAngles:log.polarizationAngles,design,...capture(diagram)}))}catch(e){throw Error(sh.name+'：'+e.message)}}const data=root.NotionExport.zip(root.NotionExport.combine(packs,dateStamp()+' 实验记录')),u=URL.createObjectURL(new Blob([data],{type:'application/zip'})),a=document.createElement('a');a.href=u;a.download=dateStamp()+'-全部实验-Notion.zip';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
root.ExperimentArchive={dateStamp,safeName,unique,source,prepare,writeFiles,folder,download,downloadNotion};if(typeof module!=='undefined')module.exports=root.ExperimentArchive;
})(typeof window!=='undefined'?window:globalThis);
